package com.hospital.system; import com.hospital.system.model.*; import com.hospital.system.dto.*; import com.hospital.system.repository.*; import com.hospital.system.service.*; import org.junit.jupiter.api.Test; import org.mockito.Mockito; import java.math.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; class PaymentServiceTest { @Test void paymentOverBalanceRejected(){PaymentRepository pr=Mockito.mock(PaymentRepository.class); BillingRepository br=Mockito.mock(BillingRepository.class); Bill b=new Bill();b.totalAmount=new BigDecimal("100.00");Mockito.when(br.one(1L)).thenReturn(Optional.of(b));Mockito.when(pr.paid(1L)).thenReturn(new BigDecimal("60.00"));PaymentService s=new PaymentService(pr,br);PaymentRequest x=new PaymentRequest();x.amount=new BigDecimal("50.00");x.paymentMethod="CASH";assertThrows(RuntimeException.class,()->s.add(1L,x));} }
